private volatile Node? _cache;
private readonly object _gate = new();

public Node World => _cache ?? Rebuild();

private Node Rebuild()
{
    lock (_gate)
        return _cache ??= BuildWorld();     // re-checked inside the lock
}

public double X
{
    get => _x;
    set { _x = value; InvalidateVisual(); }     // framework marks the element dirty
}

protected override void OnRender(DrawingContext dc)
{
    // runs after the next layout pass; nothing is redrawn while clean
    dc.DrawEllipse(Brush, Pen, new Point(_x, _y), Radius, Radius);
}
